        <div class="c-nature-box c-nature-box--side c-nature-box--access-to-pdf" data-test="entitlement-box">

            <div>
                <a href="https://wayf.springernature.com?redirect_uri&#x3D;https%3A%2F%2Fwww.nature.com%2Farticles%2Fs41576-025-00927-x" class="c-article__button" data-test="ra21">
