 ,{
    "@context": "http://schema.org",
    "@graph": [

{
    "@id": "#issue",
    "@type": "PublicationIssue",
    "issueNumber": "3","datePublished": "2019-03-04",
    "isPartOf": {
        "@id": "#periodical",
        "@type": ["PublicationVolume", "Periodical"],
        "name": "International Journal of Geographical Information Science","issn": ["1365-8816","1362-3087"],"volumeNumber": "33",
        "publisher": "Taylor & Francis Group"
      }},
    {
    "@type": "ScholarlyArticle",
    "mainEntityOfPage": "https://www.tandfonline.com/doi/full/10.1080/13658816.2018.1549734",
    "url": "https://www.tandfonline.com/doi/full/10.1080/13658816.2018.1549734",
    "isPartOf": "#periodical",
    "sameAs": "https://doi.org/10.1080/13658816.2018.1549734",
    "identifier": "10.1080/13658816.2018.1549734",
    "isAccessibleForFree": "false",
    "articleSection": "Research Articles","name": "Supporting multi-resolution out-of-core rendering of massive LiDAR point clouds through non-redundant data structures","headline": "Supporting multi-resolution out-of-core rendering of massive LiDAR point clouds through non-redundant data structures","abstract": "In recent years, the evolution and improvement of LiDAR (Light Detection and Ranging) hardware has increased the quality and quantity of the gathered data, making the storage, processing and management thereof particularly challenging. In this work we present a novel, multi-resolution, out-of-core technique, used for web-based visualization and implemented through a non-redundant, data point organization method, which we call Hierarchically Layered Tiles (HLT), and a tree-like structure called Tile Grid Partitioning Tree (TGPT). The design of these elements is mainly focused on attaining very low levels of memory consumption, disk storage usage and network traffic on both, client and server-side, while delivering high-performance interactive visualization of massive LiDAR point clouds (up to 28 billion points) on multiplatform environments (mobile devices or desktop computers). HLT and TGPT were incorporated and tested in ViLMA (Visualization for LiDAR data using a Multi-resolution Approach), our own web-based visualization software specially designed to work with massive LiDAR point clouds.",
    "description": "In recent years, the evolution and improvement of LiDAR (Light Detection and Ranging) hardware has increased the quality and quantity of the gathered data, making the storage, processing and management thereof particularly challenging. In this work we present a novel, multi-resolution, out-of-core technique, used for web-based visualization and implemented through a non-redundant, data point organization method, which we call Hierarchically Layered Tiles (HLT), and a tree-like structure called Tile Grid Partitioning Tree (TGPT). The design of these elements is mainly focused on attaining very low levels of memory consumption, disk storage usage and network traffic on both, client and server-side, while delivering high-performance interactive visualization of massive LiDAR point clouds (up to 28 billion points) on multiplatform environments (mobile devices or desktop computers). HLT and TGPT were incorporated and tested in ViLMA (Visualization for LiDAR data using a Multi-resolution Approach), our own web-based visualization software specially designed to work with massive LiDAR point clouds.",
    "author": [
        {"@type": "Person", "name": "David Deibe" },
        {"@type": "Person", "name": "Margarita Amor" },
        {"@type": "Person", "name": "Ramón Doallo" }
    ],"keywords": "out-of-core, multi-resolution, efficient data structures, web-visualization, LiDAR","pageStart": "593","pageEnd": "617",
